// Product Family 1: Storage
export interface BlobStorage {
  upload(key: string, data: Buffer): Promise<void>;
  download(key: string): Promise<Buffer>;
}

// Product Family 2: Queue
export interface MessageQueue {
  publish(topic: string, message: string): Promise<void>;
  subscribe(topic: string, handler: (msg: string) => void): void;
}

// Abstract Factory Contract
export interface CloudInfrastructureFactory {
  createStorage(): BlobStorage;
  createQueue(): MessageQueue;
}

// Concrete Family 1: AWS
export class AwsS3Storage implements BlobStorage {
  async upload(key: string, data: Buffer): Promise<void> {
    console.log(`[AWS S3] Uploading ${data.length} bytes to ${key}`);
  }
  async download(key: string): Promise<Buffer> {
    return Buffer.from("aws-data");
  }
}

export class AwsSqsQueue implements MessageQueue {
  async publish(topic: string, message: string): Promise<void> {
    console.log(`[AWS SQS] Publishing to ${topic}: ${message}`);
  }
  subscribe(topic: string, handler: (msg: string) => void): void {
    console.log(`[AWS SQS] Subscribed to ${topic}`);
  }
}

export class AwsInfrastructureFactory implements CloudInfrastructureFactory {
  createStorage(): BlobStorage { return new AwsS3Storage(); }
  createQueue(): MessageQueue { return new AwsSqsQueue(); }
}

// Concrete Family 2: GCP
export class GcpCloudStorage implements BlobStorage {
  async upload(key: string, data: Buffer): Promise<void> {
    console.log(`[GCP GCS] Uploading ${data.length} bytes to ${key}`);
  }
  async download(key: string): Promise<Buffer> {
    return Buffer.from("gcp-data");
  }
}

export class GcpPubSubQueue implements MessageQueue {
  async publish(topic: string, message: string): Promise<void> {
    console.log(`[GCP PubSub] Publishing to ${topic}: ${message}`);
  }
  subscribe(topic: string, handler: (msg: string) => void): void {
    console.log(`[GCP PubSub] Subscribed to ${topic}`);
  }
}

export class GcpInfrastructureFactory implements CloudInfrastructureFactory {
  createStorage(): BlobStorage { return new GcpCloudStorage(); }
  createQueue(): MessageQueue { return new GcpPubSubQueue(); }
}
